   351	func addHook(groups []MatcherGroup, command string) []MatcherGroup {
   352		entry := HookEntry{
   353			Type:    "command",
   354			Command: command,
   355			Timeout: 30,
   356		}
   357	
   358		// Add to an existing group with null matcher, or create a new one
   359		for i, group := range groups {
   360			if group.Matcher == nil {
   361				groups[i].Hooks = append(groups[i].Hooks, entry)
   362				return groups
   363			}
   364		}
   365		return append(groups, MatcherGroup{
   366			Matcher: nil,
   367			Hooks:   []HookEntry{entry},
   368		})
   369	}
